// Scan all messages in the thread for a PDF attachment. Skip the trigger
// email (it's the one with no PDF that brought us here). Prefer the OLDEST
// PDF in the thread (rate cons typically arrive before the tracking request).
const thread = $input.first().json;
const messages = Array.isArray(thread.messages) ? thread.messages : [];
const currentMsgId = $('Email Input').first().json.id;

function flattenParts(payload) {
  const out = [];
  function walk(p) {
    if (!p) return;
    out.push(p);
    if (Array.isArray(p.parts)) p.parts.forEach(walk);
  }
  walk(payload);
  return out;
}

const candidates = [];
for (const msg of messages) {
  if (!msg || msg.id === currentMsgId) continue;
  const parts = flattenParts(msg.payload);
  const pdfPart = parts.find(p => p && p.mimeType === 'application/pdf' && p.body && p.body.attachmentId);
  if (!pdfPart) continue;
  candidates.push({
    pdfMessageId: msg.id,
    pdfAttachmentId: pdfPart.body.attachmentId,
    pdfFilename: pdfPart.filename || 'attachment.pdf',
    internalDate: Number(msg.internalDate || 0),
  });
}

if (candidates.length === 0) return [{ json: { found: false } }];

candidates.sort((a, b) => a.internalDate - b.internalDate);
const pick = candidates[0];
return [{ json: { found: true, pdfMessageId: pick.pdfMessageId, pdfAttachmentId: pick.pdfAttachmentId, pdfFilename: pick.pdfFilename, fromTrace: '[Thread-Sourced Rate Con] ' + pick.pdfFilename } }];

// The previous Gmail node downloaded the thread message with attachments.
// Reshape the item so it matches what "Merge Attachment + Email" produces,
// so it can flow directly into Google Drive + Prep PDF Base64.
const dl = $input.first();
const binaries = dl.binary || {};
const pdfKey = Object.keys(binaries).find(k => binaries[k] && binaries[k].mimeType === 'application/pdf');
if (!pdfKey) throw new Error('Thread PDF download produced no PDF binary');

const email = $('Email Input').first().json;

return [{
  json: {
    ...email,
    attachments: pdfKey,
    _threadSourcedPdf: true,
  },
  binary: { [pdfKey]: binaries[pdfKey] },
  pairedItem: { item: 0 },
}];

// binaryMode is "separate", so item.binary[key].data can be a reference rather
// than base64. getBinaryDataBuffer() is the supported way to materialise it.
//
// pairedItem is REQUIRED. n8n only auto-pairs when this node has exactly one
// input item; the Gmail Trigger routinely delivers two rate-con emails in one
// poll, and without pairedItem every downstream `$('Node').item` expression
// throws "Paired item data ... is unavailable" — which killed both the sheet
// write and the failure alert (execution 2459, load 563593554).
const out = [];
for (let i = 0; i < items.length; i++) {
  const key = items[i].json.attachments;
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  out.push({
    json: Object.assign({}, items[i].json, { pdf_base64: buf.toString("base64") }),
    binary: items[i].binary,
    pairedItem: { item: i },
  });
}
return out;

// Resolves alert context WITHOUT relying on paired-item tracing.
// Items that arrive here from an onError branch carry no usable pairedItem,
// so any `$('Email Input').item` expression in the alert node would throw and
// the alert would be lost — the exact failure this alert exists to report.
// Everything below degrades to a placeholder instead of throwing.
let emails = [];
try { emails = $('Email Input').all(); } catch (e) { emails = []; }

let executionId = 'unknown';
try { executionId = String($execution.id); } catch (e) {}

const out = [];
for (let i = 0; i < items.length; i++) {
  const j = (items[i] && items[i].json) || {};

  // Prefer the email this item actually came from; fall back positionally,
  // then to the first email. Never throw.
  const mid = j.message_id || j.id || null;
  let email = null;
  if (mid) email = emails.find((e) => e && e.json && e.json.id === mid) || null;
  if (!email) email = emails[i] || emails[0] || null;

  const headers = (email && email.json && email.json.headers) || {};
  const subject = String(headers.subject || '').replace(/^Subject:\s*/i, '').trim() || 'Unknown';
  const from = String(headers.from || '').replace(/^From:\s*/i, '').trim() || 'Unknown';
  const received = (email && email.json && email.json.date) || 'Unknown';

  // Load # from the extraction if we got that far, else from the subject.
  const extracted =
    (j.output && j.output['Load Number']) ||
    j['Load ID'] ||
    j['Load Number'] ||
    null;
  const subjMatch =
    subject.match(/(?:load|order|booked)\D{0,12}(\d{6,12})/i) ||
    subject.match(/\b(\d{6,12})\b/);
  const loadNumber = String(extracted || (subjMatch && subjMatch[1]) || '').trim() || 'see subject';

  let reason = 'A validation gate rejected the extraction.';
  if (j.error) {
    reason = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
  }

  out.push({
    json: {
      alert_load: loadNumber,
      alert_subject: subject,
      alert_from: from,
      alert_received: received,
      alert_reason: String(reason).slice(0, 500),
      alert_execution: executionId,
      // Always a usable id so "Mark Read (Failed)" cannot fail on null.
      message_id: mid || (emails[0] && emails[0].json && emails[0].json.id) || '',
    },
    pairedItem: { item: i },
  });
}
return out;
